"""Deepgram Nova ASR engine."""

import json
from typing import Any, Dict, List, Optional
from urllib.parse import urlencode

from websockets.protocol import State

from rasa.core.channels.voice_stream.asr.asr_engine import ASRLanguageMapEntry
from rasa.core.channels.voice_stream.asr.asr_event import (
    ASREvent,
    NewTranscript,
    UserIsSpeaking,
)
from rasa.core.channels.voice_stream.audio_bytes import AudioFormat

from .base import _DeepgramASRBase
from .config import DeepgramASRConfig
from .constants import (
    DEEPGRAM_API_V1,
    DEFAULT_ENDPOINT,
    DEFAULT_ENDPOINTING,
    DEFAULT_NOVA_MODEL,
    DEFAULT_SMART_FORMAT,
    DEFAULT_UTTERANCE_END_MS,
)


def _extract_transcript(data: Dict[str, Any]) -> Optional[str]:
    """Return the first transcript from a v1 ``Results`` frame, if present."""
    channel = data.get("channel")
    if not isinstance(channel, dict):
        return None

    alternatives = channel.get("alternatives")
    if not isinstance(alternatives, list) or not alternatives:
        return None

    first_alternative = alternatives[0]
    if not isinstance(first_alternative, dict):
        return None

    transcript = first_alternative.get("transcript")
    if not transcript:
        return None

    return str(transcript)


class DeepgramASR(_DeepgramASRBase[DeepgramASRConfig]):
    """Deepgram Nova ASR engine using the ``/v1/listen`` API."""

    api_version = DEEPGRAM_API_V1

    @classmethod
    def name(cls) -> str:
        return "deepgram"

    def __init__(
        self,
        rasa_language: str,
        format: AudioFormat,
        config: Optional[DeepgramASRConfig] = None,
        additional_languages: Optional[List[str]] = None,
    ) -> None:
        super().__init__(rasa_language, format, config, additional_languages)
        self._accumulated_transcript = ""

    def _get_query_params(self) -> str:
        params: Dict[str, Any] = {
            "encoding": self._encoding_for(self.audio_format),
            "sample_rate": self.audio_format.sample_rate,
            "endpointing": self.config.endpointing,
            "vad_events": "true",
            "language": self.current_language_config.engine_language_key,
            "interim_results": "true",
            "model": self.current_language_config.model,
            "smart_format": str(self.config.smart_format).lower(),
        }
        if self.config.utterance_end_ms and self.config.utterance_end_ms > 0:
            params["utterance_end_ms"] = self.config.utterance_end_ms
        return urlencode(params)

    def engine_event_to_asr_event(self, event: Any) -> Optional[ASREvent]:
        """Translate a v1 websocket message into a Rasa ASR event."""
        data = json.loads(event) if isinstance(event, (str, bytes)) else event
        data_type = data.get("type")

        if data_type == "Results":
            transcript = _extract_transcript(data)

            if data.get("is_final"):
                transcript_text = transcript or ""
                if data.get("speech_final"):
                    full_transcript = (
                        self._accumulated_transcript.strip()
                        + " "
                        + transcript_text.strip()
                    ).strip()
                    self._accumulated_transcript = ""
                    if full_transcript:
                        return NewTranscript(full_transcript)
                else:
                    self._accumulated_transcript = (
                        self._accumulated_transcript.strip()
                        + " "
                        + transcript_text.strip()
                    ).strip()
            elif transcript:
                return UserIsSpeaking(transcript)

        elif data_type == "UtteranceEnd" and self._accumulated_transcript:
            transcript = self._accumulated_transcript
            self._accumulated_transcript = ""
            return NewTranscript(transcript)

        return None

    async def send_keep_alive(self) -> None:
        """Send a ``KeepAlive`` frame to the v1 websocket."""
        if self.asr_socket is None or self.asr_socket.state is not State.OPEN:
            return
        await self.asr_socket.send(json.dumps({"type": "KeepAlive"}))

    @staticmethod
    def get_default_config(rasa_language: str) -> DeepgramASRConfig:
        """Return the default Nova configuration."""
        return DeepgramASRConfig(
            endpoint=DEFAULT_ENDPOINT,
            endpointing=DEFAULT_ENDPOINTING,
            smart_format=DEFAULT_SMART_FORMAT,
            utterance_end_ms=DEFAULT_UTTERANCE_END_MS,
            language_map={
                rasa_language: ASRLanguageMapEntry(
                    language="en",
                    model=DEFAULT_NOVA_MODEL,
                ),
            },
        )

    @classmethod
    def from_config_dict(
        cls,
        config: Dict[str, Any],
        format: AudioFormat,
        rasa_language: str,
        additional_languages: Optional[List[str]] = None,
    ) -> "DeepgramASR":
        """Create a Nova ASR engine from a raw configuration dictionary."""
        return cls(
            rasa_language=rasa_language,
            format=format,
            config=DeepgramASRConfig.model_validate(config or {}),
            additional_languages=additional_languages,
        )
